flight_plan.header:
#include "modules/digital_cam/uart_cam_ctrl.h"
#include "firmwares/fixedwing/nav.h"
static inline bool demo_in_survey(uint8_t southwest, uint8_t northeast)
{
  const float east = (*stateGetPositionUtm_f()).east - nav_utm_east0;
  const float north = (*stateGetPositionUtm_f()).north - nav_utm_north0;
  const float altitude = GetPosAlt();
  const float roll = (*stateGetNedToBodyEulers_f()).phi;
  const float pitch = (*stateGetNedToBodyEulers_f()).theta;
  if (!nav_in_segment) return false;
  if (!isfinite(east)) return false;
  if (!isfinite(north)) return false;
  if (!isfinite(altitude)) return false;
  if (!isfinite(roll)) return false;
  if (!isfinite(pitch)) return false;
  if (!LessThan(fabsf(roll), RadOfDeg(10.f))) return false;
  if (!LessThan(fabsf(pitch), RadOfDeg(10.f))) return false;
  if (!LessThan(fabsf(altitude - WaypointAlt(southwest)), 5.f)) return false;
  if (!LessThan(WaypointX(southwest) + 5.f, east)) return false;
  if (!LessThan(east, WaypointX(northeast) - 5.f)) return false;
  if (!LessThan(WaypointY(southwest) + 5.f, north)) return false;
  return LessThan(north, WaypointY(northeast) - 5.f);
}
static inline void demo_survey_capture(uint8_t southwest, uint8_t northeast)
{
  dc_autoshoot = demo_in_survey(southwest, northeast) ? DC_AUTOSHOOT_DISTANCE : DC_AUTOSHOOT_STOP;
}
